effect.shader:
vec4 tex(vec2 p){ return texture2DCv(inputImg.texture, p); }
void main(){
vec4 src = tex(acScreenNorm);
float p = mix(clamp(progress, 0.0, 1.0), 0.5 - 0.5 * cos(acTime * speed * 3.14159265359), clamp(auto, 0.0, 1.0));
float k = clamp(p * 2.0, 0.0, 1.0);
float vis = clamp(2.0 - p * 2.0, 0.0, 1.0);
vec3 c = mix(src.rgb, vec3(0.0), k);
gl_FragColor = vec4(c, src.a * vis);
}
